    std::string greeting = "Hello";
    std::string name = "FuKai";
    std::string message = greeting + ", " + name + "!";
    message = message + " Welcome";

    std::println("{}", message);
    // 先数到 26，再让 length() 验证
    std::println("长度 = {}", message.length());

    std::string s = "";
    std::println("是空的吗 = {}", s.empty());
    return 0;
}

